package dev.algorithmlearning.api.problems.data;
import dev.algorithmlearning.api.problems.application.*; import java.util.*; import org.springframework.stereotype.Repository;
@Repository public class JpaSolutionRepository implements SolutionRepository {private final SolutionJpaRepository data;public JpaSolutionRepository(SolutionJpaRepository data){this.data=data;}public Solution save(Solution s){return map(data.save(new SolutionEntity(s.id(),s.problemId(),s.language(),s.code(),s.explanation(),s.createdAt(),s.updatedAt())));}public List<Solution> findAllByProblemId(UUID id){return data.findByProblemIdOrderByCreatedAtAscIdAsc(id).stream().map(this::map).toList();}public Optional<Solution> findByIdAndUserId(UUID id,UUID owner){return data.findByIdAndUserId(id,owner).map(this::map);}public void deleteById(UUID id){data.deleteById(id);}private Solution map(SolutionEntity e){return new Solution(e.id,e.problemId,e.language,e.code,e.explanation,e.createdAt,e.updatedAt);}}
